{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Holistic & Integrative Support</title>
  <meta name="description" content="A warm, evidence-informed approach to whole-person care in {{CITY}}, {{STATE}}. Book a conversation to explore options.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <div class="site-root">
    <header class="topbar">
      <div class="brand">
        <svg class="logo" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="22" fill="url(#g)" stroke="#fff" stroke-opacity="0.12" stroke-width="1"/><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="#9ad3c7"/><stop offset="1" stop-color="#8aa7e6"/></linearGradient></defs></svg>
        <div>
          <div class="name">{{BUSINESS_NAME}}</div>
          <div class="tag">Gentle, informed care for everyday momentum</div>
        </div>
      </div>
      <nav class="nav">
        <a href="index.html" class="active">Home</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Health Topics</a>
        <a href="approach.html">Way We Work</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Story</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
      <div class="contact">
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </header>

    <main>
      <section class="hero">
        <svg class="pattern" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 200" preserveAspectRatio="none">
          <defs>
            <pattern id="p1" width="40" height="40" patternUnits="userSpaceOnUse">
              <rect width="40" height="40" fill="rgba(255,255,255,0.03)"/>
              <circle cx="20" cy="20" r="6" fill="rgba(255,255,255,0.04)"/>
            </pattern>
          </defs>
          <rect width="100%" height="100%" fill="url(#p1)" />
        </svg>
        <div class="hero-inner glass">
          <h1>Care that listens — then maps a gentle path forward</h1>
          <p class="lead">We combine practical evidence, lifestyle coaching, and supportive therapies to help you feel more regulated and present. Meet with our clinicians in {{CITY}}, {{STATE}} or remotely.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">Start a conversation</a>
            <a class="btn ghost" href="book.html">See availability</a>
          </div>
          <ul class="meta">
            <li>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
            <li>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
          </ul>
        </div>
      </section>

      <section class="social-proof">
        <div class="glass">
          <h2>Voices of clarity</h2>
          <p class="sm">A rotating proof gallery from people who've worked with our team and organizations who partner with our clinicians.</p>
          <div class="proof-wrap">
            <div class="testimonials" id="testimonials" aria-live="polite">
              <!-- testimonials injected by JS -->
            </div>
            <aside class="badges">
              <div class="badge" data-tip="Board certified clinicians with integrative training">🏥<span class="tip">Board certified clinicians with integrative training</span></div>
              <div class="badge" data-tip="Partnered with community research initiatives">🔬<span class="tip">Partnered with community research initiatives</span></div>
              <div class="badge" data-tip="Featured in regional wellness publications">📰<span class="tip">Featured in regional wellness publications</span></div>
            </aside>
          </div>
        </div>
      </section>

      <section class="benefits">
        <div class="glass">
          <h2>What people often notice first</h2>
          <ul class="benefit-list">
            <li><strong>Smaller steps, clearer days:</strong> Simple practices matched to your routine rather than dramatic change.</li>
            <li><strong>Context-aware plans:</strong> We listen for what matters in your life rhythm and design support around it.</li>
            <li><strong>Evidence-forward options:</strong> Clear explanations of what might help and why, with risks and benefits.</li>
          </ul>

          <div class="pricing-mini">
            <h3>Compare: Monthly vs Package</h3>
            <div class="toggle">
              <button id="pricing-toggle" aria-pressed="false">Monthly</button>
              <div class="labels"><span>Monthly</span><span>Package</span></div>
            </div>
            <div class="plans">
              <div class="plan">
                <div class="plan-name">Seasonal Tune</div>
                <div class="plan-price" data-month="85" data-package="220">$<span class="amount">85</span></div>
                <div class="plan-note">Short-term check-ins and focused coaching</div>
              </div>
              <div class="plan">
                <div class="plan-name">Root & Restore</div>
                <div class="plan-price" data-month="195" data-package="560">$<span class="amount">195</span></div>
                <div class="plan-note">Multi-session path to steady habits and review</div>
              </div>
              <div class="plan">
                <div class="plan-name">Foundations Package</div>
                <div class="plan-price" data-month="0" data-package="980">$<span class="amount">0</span></div>
                <div class="plan-note">Comprehensive package with intake and follow-ups</div>
              </div>
            </div>
            <p class="footnote">Prices are illustrative. A clinician will review appropriate care options; nothing here is a promise of outcome.</p>
          </div>
        </div>
      </section>

      <section class="process">
        <div class="glass">
          <h2>How we typically proceed</h2>
          <ol class="steps">
            <li><strong>Listen & map:</strong> Intake conversation to understand your story and priorities.</li>
            <li><strong>Co-create a plan:</strong> We suggest options — lifestyle, supports, and monitoring — with clear rationale.</li>
            <li><strong>Try and tune:</strong> Short cycles of practice, check-ins, and adjustments.</li>
            <li><strong>Reflect & transition:</strong> Prepare a sustainable rhythm with community or self-directed supports.</li>
          </ol>
        </div>
      </section>

      <section class="faq">
        <div class="glass">
          <h2>Questions people ask</h2>
          <details>
            <summary>What can I expect from a first visit?</summary>
            <p>A focused conversation, background review, and collaborative planning for next steps. We provide educational guidance; clinical decisions are personalized.</p>
          </details>
          <details>
            <summary>Do you treat specific conditions?</summary>
            <p>We provide supportive, holistic approaches for many concerns. See our Health Topics page for disclaimers and condition-specific educational resources.</p>
          </details>
          <details>
            <summary>How does telehealth work?</summary>
            <p>Secure video appointments are available. We will share preparation steps and materials ahead of the visit.</p>
          </details>
        </div>
      </section>

      <section class="cta">
        <div class="glass cta-inner">
          <h2>Ready to explore what might shift for you?</h2>
          <p>Start with a short conversation — we’ll listen first and explain options without pressure.</p>
          <div class="cta-actions">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="contact.html">Ask a question</a>
          </div>
        </div>
      </section>
    </main>

    <footer class="site-footer">
      <div class="footer-inner">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <div>{{CITY}}, {{STATE}}</div>
        </div>
        <div>
          <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
        </div>
        <div class="small">© <span id="year"></span></div>
      </div>
    </footer>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
