{"path":"assets/css/styles.css","content":":root{--bg:#0f1720;--glass:rgba(255,255,255,0.06);--accent1:#9ad3c7;--accent2:#8aa7e6;--muted:#cbd5e1;--glass-2:rgba(255,255,255,0.03)}*{box-sizing:border-box}html,body{height:100%}body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:linear-gradient(180deg,#071021 0%,#0d1b2a 60%);color:var(--muted);-webkit-font-smoothing:antialiased}
.site-root{min-height:100vh;display:flex;flex-direction:column}
.topbar{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;gap:16px}
.brand{display:flex;align-items:center;gap:12px}
.logo{width:46px;height:46px;border-radius:8px;box-shadow:0 4px 18px rgba(10,10,10,0.6)}
.name{font-weight:700;color:#fff}
.tag{font-size:13px;color:var(--muted)}
.nav{display:flex;gap:14px}
.nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.active, .nav a:hover{background:var(--glass);color:#fff}
.contact .btn{padding:8px 12px;border-radius:8px;background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#06233a;text-decoration:none;font-weight:600}
.btn{display:inline-block;padding:8px 14px;border-radius:10px;background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);text-decoration:none}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#06233a;border:none}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.06)}
.hero{position:relative;padding:48px 20px;background-image:url('assets/img/pattern.svg');background-size:cover}
.hero .hero-inner{max-width:980px;margin:0 auto;padding:30px;border-radius:14px;backdrop-filter:blur(10px);background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.06)}
.hero h1{color:#fff;margin:0 0 12px;font-size:28px}
.lead{color:rgba(255,255,255,0.87);margin:0 0 18px}
.hero-ctas{display:flex;gap:12px;margin-bottom:14px}
.meta{display:flex;gap:14px;padding:0;margin:0;list-style:none;color:var(--muted);font-size:13px}
.social-proof,.benefits,.process,.faq,.cta{padding:36px 20px}
.glass{max-width:1000px;margin:0 auto;padding:22px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.02),rgba(255,255,255,0.01));backdrop-filter:blur(6px);border:1px solid rgba(255,255,255,0.04)}
.social-proof h2,.benefits h2,.process h2,.faq h2,.cta h2{color:#fff}
.proof-wrap{display:flex;gap:20px;align-items:flex-start}
.testimonials{flex:1;min-height:130px}
.testimonial{padding:14px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),rgba(255,255,255,0.00));border:1px solid rgba(255,255,255,0.03);color:var(--muted)}
.testimonial p{margin:0 0 8px}
.testimonial .who{font-size:13px;color:#dbeafe}
.badges{width:160px;display:flex;flex-direction:column;gap:10px}
.badge{position:relative;padding:10px;border-radius:10px;background:var(--glass-2);text-align:center;cursor:default}
.badge .tip{position:absolute;left:110%;top:50%;transform:translateY(-50%);white-space:nowrap;background:#0b1220;color:#fff;padding:8px;border-radius:8px;box-shadow:0 6px 20px rgba(0,0,0,0.6);opacity:0;pointer-events:none;transition:opacity .18s}
.badge:hover .tip{opacity:1}
.benefit-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px;padding:0;margin:14px 0 20px;list-style:none}
.pricing-mini{margin-top:10px}
.toggle{display:flex;align-items:center;gap:10px;margin:10px 0}
#pricing-toggle{padding:6px 12px;border-radius:999px;border:1px solid rgba(255,255,255,0.06);background:transparent;color:var(--muted);cursor:pointer}
.plans{display:flex;gap:12px}
.plan{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),rgba(255,255,255,0.00));border:1px solid rgba(255,255,255,0.03)}
.plan-name{font-weight:700;color:#fff;margin-bottom:6px}
.plan-price{font-size:20px;color:var(--accent2);margin-bottom:6px}
.plan-note{font-size:13px;color:var(--muted)}
.footnote{font-size:12px;color:rgba(255,255,255,0.6)}
.steps{padding-left:18px}
.steps li{margin:10px 0}
.faq details{margin:8px 0;padding:10px;border-radius:8px;background:rgba(255,255,255,0.01)}
.site-footer{margin-top:auto;padding:18px 20px;color:var(--muted)}
.footer-inner{max-width:1000px;margin:0 auto;display:flex;justify-content:space-between;align-items:center}
.small{font-size:13px;color:rgba(255,255,255,0.5)}
@media(max-width:820px){.nav{display:none}.proof-wrap{flex-direction:column}.plans{flex-direction:column}}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Year
  document.getElementById('year').textContent = new Date().getFullYear();

  // Testimonials data
  const testimonials = [
    {text:'After a few sessions I could notice small shifts that added up — practical steps I could keep.',who:'— A. (client)'} ,
    {text:'The team helped me reframe daily choices into realistic routines rather than big rules.',who:'— J. (client)'} ,
    {text:'Clear communication, options explained with pros and cons; I felt respected in decisions.',who:'— R. (client)'}
  ];

  const testimonialsEl = document.getElementById('testimonials');
  let current = 0;

  function renderTestimonial(i){
    const t = testimonials[i];
    testimonialsEl.innerHTML = '';
    const div = document.createElement('div');
    div.className = 'testimonial';
    const p = document.createElement('p');
    p.textContent = t.text;
    const who = document.createElement('div');
    who.className = 'who';
    who.textContent = t.who;
    div.appendChild(p);
    div.appendChild(who);
    testimonialsEl.appendChild(div);
  }

  renderTestimonial(current);
  setInterval(()=>{
    current = (current + 1) % testimonials.length;
    // simple fade out/in
    testimonialsEl.style.opacity = 0;
    setTimeout(()=>{ renderTestimonial(current); testimonialsEl.style.opacity = 1; }, 300);
  },4500);

  // Badge tooltips are handled via CSS showing .tip on :hover; also show on focus for accessibility
  const badges = Array.from(document.querySelectorAll('.badge'));
  badges.forEach(b=>{ b.tabIndex = 0; b.addEventListener('focus', ()=> b.querySelector('.tip').style.opacity = 1); b.addEventListener('blur', ()=> b.querySelector('.tip').style.opacity = 0); });

  // Pricing comparator
  const toggle = document.getElementById('pricing-toggle');
  let mode = 'monthly';
  const amountEls = Array.from(document.querySelectorAll('.plan-price'));

  // Helper: animate value in child .amount
  function animateAmount(el, from, to, duration){
    const span = el.querySelector('.amount');
    const start = performance.now();
    function step(now){
      const t = Math.min(1, (now - start)/duration);
      const eased = t<.5 ? 2*t*t : -1 + (4 - 2*t)*t; // ease
      const val = Math.round(from + (to - from) * eased);
      span.textContent = val;
      if(t < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  // Initialize prices
  amountEls.forEach(el=>{
    const m = parseInt(el.dataset.month,10) || 0;
    const p = parseInt(el.dataset.package,10) || 0;
    el.querySelector('.amount').textContent = m;
    // store values
  });

  toggle.addEventListener('click', ()=>{
    mode = mode === 'monthly' ? 'package' : 'monthly';
    toggle.textContent = mode === 'monthly' ? 'Monthly' : 'Package';
    toggle.setAttribute('aria-pressed', mode === 'package');
    amountEls.forEach(el=>{
      const from = parseInt(el.querySelector('.amount').textContent,10) || 0;
      const to = mode === 'monthly' ? parseInt(el.dataset.month,10) : parseInt(el.dataset.package,10);
      animateAmount(el, from, to, 550);
    });
  });

  // Ensure keyboard toggle: space/enter toggles
  toggle.addEventListener('keydown', (e)=>{ if(e.key === ' ' || e.key === 'Enter'){ e.preventDefault(); toggle.click(); } });

})();"} 
